/* BiblioWeb — protótipo acadêmico local. Todos os dados ficam no navegador. */
(() => {
  'use strict';
  const KEY='biblioweb_novo_v1';
  const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
  const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
  const addDays=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
  const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'—';
  const uid=prefix=>prefix+'-'+Math.random().toString(36).slice(2,8).toUpperCase();
  const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const seed=()=>({
    users:[
      {id:'U001',name:'Ana Clara Souza',email:'ana@biblioweb.local',registration:'2024001',role:'student',course:'Análise e Desenvolvimento de Sistemas',active:true},
      {id:'U002',name:'Bruno Martins',email:'bruno@biblioweb.local',registration:'2024002',role:'student',course:'Administração',active:true},
      {id:'U003',name:'Marina Oliveira',email:'marina@biblioweb.local',registration:'BIB001',role:'librarian',course:'Bibliotecária',active:true},
      {id:'U004',name:'Lucas Ferreira',email:'lucas@biblioweb.local',registration:'2024003',role:'student',course:'Engenharia de Software',active:true},
      {id:'U005',name:'Camila Rocha',email:'camila@biblioweb.local',registration:'2024004',role:'student',course:'Pedagogia',active:true}
    ],
    books:[
      {id:'B001',title:'Algoritmos e lógica de programação',author:'André Luiz Villar',publisher:'Érica',year:2023,isbn:'9788536531452',type:'Livro',subject:'Computação',edition:'4ª edição',description:'Uma introdução prática à lógica de programação, algoritmos, estruturas de controle e resolução de problemas computacionais.',cover:1,copies:[{id:'EX001',location:'Estante A • 001',status:'available'},{id:'EX002',location:'Estante A • 001',status:'borrowed'},{id:'EX003',location:'Estante A • 001',status:'available'}]},
      {id:'B002',title:'Administração: teoria e prática',author:'Idalberto Chiavenato',publisher:'Atlas',year:2022,isbn:'9788597023688',type:'Livro',subject:'Administração',edition:'6ª edição',description:'Fundamentos da administração, planejamento, organização, direção e controle aplicados às organizações.',cover:2,copies:[{id:'EX004',location:'Estante B • 014',status:'borrowed'},{id:'EX005',location:'Estante B • 014',status:'borrowed'}]},
      {id:'B003',title:'O pequeno príncipe',author:'Antoine de Saint-Exupéry',publisher:'Agir',year:2021,isbn:'9788522005230',type:'Livro',subject:'Literatura',edition:'1ª edição',description:'Uma narrativa clássica sobre amizade, afeto, responsabilidade e o olhar sensível sobre o mundo.',cover:3,copies:[{id:'EX006',location:'Estante L • 006',status:'available'},{id:'EX007',location:'Estante L • 006',status:'available'}]},
      {id:'B004',title:'Engenharia de software moderna',author:'Marco Tulio Valente',publisher:'Independente',year:2020,isbn:'9786500019501',type:'Livro',subject:'Computação',edition:'1ª edição',description:'Conceitos e práticas contemporâneas de engenharia de software, arquitetura, testes e evolução de sistemas.',cover:4,copies:[{id:'EX008',location:'Estante C • 021',status:'borrowed'}]},
      {id:'B005',title:'Metodologia do trabalho científico',author:'Antônio Joaquim Severino',publisher:'Cortez',year:2019,isbn:'9788524924486',type:'Livro',subject:'Educação',edition:'24ª edição',description:'Orientações para leitura, pesquisa, documentação e elaboração de trabalhos acadêmicos e científicos.',cover:5,copies:[{id:'EX009',location:'Estante D • 009',status:'available'},{id:'EX010',location:'Estante D • 009',status:'available'}]},
      {id:'B006',title:'Introdução à ciência de dados',author:'Rafael A. C. B. de Souza',publisher:'Novatec',year:2024,isbn:'9788575228910',type:'Livro',subject:'Computação',edition:'1ª edição',description:'Conceitos essenciais de análise de dados, preparação, visualização e interpretação de informações.',cover:6,copies:[{id:'EX011',location:'Estante A • 027',status:'available'}]},
      {id:'B007',title:'Quarto de despejo',author:'Carolina Maria de Jesus',publisher:'Ática',year:2020,isbn:'9788508171279',type:'Livro',subject:'Literatura',edition:'10ª edição',description:'Diário marcante que retrata o cotidiano, a desigualdade e a resistência na experiência urbana brasileira.',cover:7,copies:[{id:'EX012',location:'Estante L • 012',status:'borrowed'}]},
      {id:'B008',title:'Gestão de projetos',author:'Harold Kerzner',publisher:'Bookman',year:2021,isbn:'9788582605301',type:'Livro',subject:'Administração',edition:'3ª edição',description:'Abordagem abrangente dos processos, ferramentas e práticas de gerenciamento de projetos.',cover:8,copies:[{id:'EX013',location:'Estante B • 031',status:'available'}]},
      {id:'B009',title:'Banco de dados: projeto e implementação',author:'Carlos Alberto Heuser',publisher:'Bookman',year:2018,isbn:'9788582604601',type:'Livro',subject:'Computação',edition:'6ª edição',description:'Modelagem conceitual, relacional e implementação de bancos de dados.',cover:1,copies:[{id:'EX014',location:'Estante A • 032',status:'borrowed'},{id:'EX015',location:'Estante A • 032',status:'borrowed'}]},
      {id:'B010',title:'Didática',author:'José Carlos Libâneo',publisher:'Cortez',year:2017,isbn:'9788524916031',type:'Livro',subject:'Educação',edition:'2ª edição',description:'Fundamentos da prática docente, planejamento de ensino e organização do trabalho pedagógico.',cover:3,copies:[{id:'EX016',location:'Estante E • 004',status:'available'}]},
      {id:'B011',title:'Cálculo: volume 1',author:'James Stewart',publisher:'Cengage',year:2016,isbn:'9788522125832',type:'Livro',subject:'Engenharia',edition:'8ª edição',description:'Texto de referência para estudo de limites, derivadas, integrais e aplicações.',cover:4,copies:[{id:'EX017',location:'Estante F • 011',status:'available'}]},
      {id:'B012',title:'Pesquisa em educação',author:'Menga Lüdke e Marli André',publisher:'EPU',year:2015,isbn:'9788512122506',type:'Livro',subject:'Educação',edition:'2ª edição',description:'Introdução aos fundamentos e procedimentos da pesquisa qualitativa em educação.',cover:5,copies:[{id:'EX018',location:'Estante E • 016',status:'available'}]}
    ],loans:[
      {id:'L001',userId:'U001',copyId:'EX002',bookId:'B001',loanDate:addDays(today(),-5),dueDate:addDays(today(),9),status:'active',renewals:0},
      {id:'L002',userId:'U002',copyId:'EX004',bookId:'B002',loanDate:addDays(today(),-17),dueDate:addDays(today(),-3),status:'active',renewals:0},
      {id:'L003',userId:'U003',copyId:'EX008',bookId:'B004',loanDate:addDays(today(),-7),dueDate:addDays(today(),7),status:'active',renewals:0},
      {id:'L004',userId:'U004',copyId:'EX012',bookId:'B007',loanDate:addDays(today(),-2),dueDate:addDays(today(),12),status:'active',renewals:0}
    ],reservations:[{id:'R001',userId:'U005',bookId:'B002',date:addDays(today(),-1),status:'waiting',position:1}],history:[],basket:[],session:null,settings:{loanDays:14,maxLoans:3,maxRenewals:2,holdDays:2}}
  );
  let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed()}catch{db=seed()}
  function save(){localStorage.setItem(KEY,JSON.stringify(db))}
  function book(id){return db.books.find(b=>b.id===id)} function user(id){return db.users.find(u=>u.id===id)} function copy(id){for(const b of db.books){const c=b.copies.find(x=>x.id===id);if(c)return c}return null}
  function activeLoans(userId){return db.loans.filter(l=>l.status==='active'&&(!userId||l.userId===userId))}
  function availableCopies(b){return b.copies.filter(c=>c.status==='available').length}
  function toast(msg,type='success'){const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;$('#toast-region').append(el);setTimeout(()=>el.remove(),3600)}
  function openModal(title,html,kicker='BIBLIOWEB',wide=false){$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;$('#modal').classList.toggle('wide',wide);$('#modal-backdrop').hidden=false;document.body.style.overflow='hidden';$('#modal-close').focus()}
  function closeModal(){ $('#modal-backdrop').hidden=true;document.body.style.overflow='';$('#modal').classList.remove('wide') }
  function cover(b,large=false){return `<div class="book-cover cover-${b.cover||1}"><span class="cover-mark">BIBLIOWEB</span><strong>${escapeHTML(b.title)}</strong><small>${escapeHTML(b.author)}</small></div>`}
  function availability(b){return availableCopies(b)>0?`<span class="status available">Disponível</span>`:`<span class="status borrowed">Emprestado</span>`}
  let visibleBooks=8,viewMode='grid',lastQuery='';
  function filteredBooks(){let q=$('#search-query').value.trim().toLocaleLowerCase('pt-BR'),field=$('#search-field').value,type=$('#filter-type').value,subject=$('#filter-subject').value,year=$('#filter-year').value,avail=$('#filter-availability').value;let arr=db.books.filter(b=>{let fields={title:b.title,author:b.author,subject:b.subject,publisher:b.publisher,isbn:b.isbn,all:[b.title,b.author,b.subject,b.publisher,b.isbn,b.year].join(' ')};let ok=!q||String(fields[field]??fields.all).toLocaleLowerCase('pt-BR').includes(q);return ok&&(!type||b.type===type)&&(!subject||b.subject===subject)&&(!year||String(b.year)===year)&&(!avail||(avail==='available'?availableCopies(b)>0:availableCopies(b)===0))});let sort=$('#sort-books').value;if(sort==='title')arr.sort((a,b)=>a.title.localeCompare(b.title,'pt-BR'));if(sort==='year')arr.sort((a,b)=>b.year-a.year);return arr}
  function renderCatalog(){const arr=filteredBooks(),shown=arr.slice(0,visibleBooks);$('#catalog-results').classList.toggle('list-view',viewMode==='list');$('#catalog-results').innerHTML=shown.map(b=>`<article class="book-card"><div class="book-cover-wrap">${cover(b)}${availableCopies(b)?'<span class="availability-pill">Disponível</span>':'<span class="availability-pill unavailable">Emprestado</span>'}</div><div class="book-card-body"><div class="book-type">${escapeHTML(b.type)} • ${escapeHTML(b.subject)}</div><h3 class="book-title">${escapeHTML(b.title)}</h3><div class="book-author">${escapeHTML(b.author)}</div><div class="book-meta"><span>${b.year}</span><span>${b.copies.length} exemplar(es)</span></div><div class="book-card-actions"><button class="btn btn-outline" data-detail="${b.id}">Detalhes</button><button class="btn btn-primary" data-reserve="${b.id}" ${availableCopies(b)>0?'disabled title="Há exemplar disponível para empréstimo presencial"':''}>Reservar</button><button class="icon-button" data-basket="${b.id}" aria-label="Adicionar à cesta">＋</button></div></div></article>`).join('');$('#no-results').hidden=arr.length>0;$('#catalog-count').textContent=`${shown.length} de ${arr.length} título(s)`;$('#result-summary').textContent=lastQuery?`Resultados para “${lastQuery}”`:`${arr.length} título(s) no acervo`;$('#load-more').hidden=shown.length>=arr.length||arr.length===0;$('#stat-titles').textContent=db.books.length.toLocaleString('pt-BR');$('#stat-copies').textContent=db.books.reduce((n,b)=>n+b.copies.length,0).toLocaleString('pt-BR')}
  function goCatalog(){document.querySelector('#catalogo').scrollIntoView({behavior:'smooth'});$('#search-query').focus({preventScroll:true})}
  function openBook(id){const b=book(id);if(!b)return;let copies=b.copies.map(c=>`<tr><td>${escapeHTML(c.id)}</td><td>${escapeHTML(c.location)}</td><td>${c.status==='available'?'<span class="status available">Disponível</span>':c.status==='reserved'?'<span class="status ready">Reservado</span>':'<span class="status borrowed">Emprestado</span>'}</td></tr>`).join('');openModal('Detalhes do material',`<div class="detail-layout"><div class="detail-cover">${cover(b,true)}</div><div class="detail-data"><div class="book-type">${escapeHTML(b.type)} • ${escapeHTML(b.subject)}</div><h3>${escapeHTML(b.title)}</h3><div class="detail-author">${escapeHTML(b.author)}</div><p class="detail-description">${escapeHTML(b.description)}</p><div class="detail-meta"><div><span>Editora</span><strong>${escapeHTML(b.publisher)}</strong></div><div><span>Ano</span><strong>${b.year}</strong></div><div><span>Edição</span><strong>${escapeHTML(b.edition)}</strong></div><div><span>ISBN</span><strong>${escapeHTML(b.isbn)}</strong></div></div><div>${availability(b)} <small style="color:#81919a"> ${availableCopies(b)} de ${b.copies.length} exemplar(es) disponível(is)</small></div></div></div><h3 style="font:700 13px Manrope;color:var(--navy);margin:20px 0 8px">Exemplares e localização</h3><div class="table-wrap"><table class="copy-table"><thead><tr><th>Tombo</th><th>Localização</th><th>Situação</th></tr></thead><tbody>${copies}</tbody></table></div><div class="form-actions"><button class="btn btn-outline" data-modal-action="basket" data-id="${b.id}">Adicionar à cesta</button>${availableCopies(b)?'<span class="form-help">Procure o balcão para realizar o empréstimo.</span>':`<button class="btn btn-primary" data-modal-action="reserve" data-id="${b.id}">Solicitar reserva</button>`}</div>`,'CONSULTA AO ACERVO',true)}
  function addBasket(id){if(!db.basket.includes(id)){db.basket.push(id);save();$('#basket-count').textContent=db.basket.length;toast('Material adicionado à sua cesta.')}else toast('Este material já está na sua cesta.','error')}
  function openBasket(){let items=db.basket.map(id=>book(id)).filter(Boolean);openModal('Minha cesta',items.length?`${items.map(b=>`<div class="basket-item"><div><strong>${escapeHTML(b.title)}</strong><small>${escapeHTML(b.author)} • ${b.year}</small></div><button data-remove-basket="${b.id}">Remover</button></div>`).join('')}<div class="form-actions"><button class="btn btn-outline" id="basket-clear">Limpar cesta</button><button class="btn btn-primary" id="basket-print">Imprimir lista</button></div>`:'<div class="tab-empty">Sua cesta está vazia.<br>Adicione títulos para montar uma lista de consulta.</div>','CESTA DE MATERIAIS')}
  function openLogin(role='student'){const isAdmin=role==='librarian';openModal(isAdmin?'Acesso da equipe':'Acesso do usuário',`<div class="demo-note"><strong>Ambiente de demonstração acadêmica.</strong> Use uma das contas abaixo. A senha é fictícia e não é validada pelo protótipo.</div><div class="login-layout"><form id="login-form"><div class="form-field"><label for="login-id">Matrícula ou e-mail</label><input id="login-id" required placeholder="Digite sua matrícula ou e-mail"></div><div class="form-field" style="margin-top:12px"><label for="login-password">Senha</label><input id="login-password" type="password" required placeholder="Digite qualquer senha"></div><div class="form-field" style="margin-top:12px"><label for="login-role">Tipo de acesso</label><select id="login-role"><option value="student" ${isAdmin?'':'selected'}>Estudante</option><option value="librarian" ${isAdmin?'selected':''}>Bibliotecário(a)</option></select></div><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancelar</button><button class="btn btn-primary" type="submit">Entrar →</button></div></form><aside class="login-side"><h3>Contas para demonstração</h3><p>Selecione uma conta para preencher o acesso automaticamente.</p>${db.users.filter(u=>u.active).map(u=>`<div class="demo-account"><span><strong>${escapeHTML(u.name)}</strong><br>${u.role==='librarian'?'Bibliotecária':'Estudante'} • ${escapeHTML(u.registration)}</span><button type="button" data-fill-login="${u.id}">Usar conta</button></div>`).join('')}</aside></div>`,'MEU BIBLIOWEB')}
  function current(){return db.session?user(db.session):null}
  function login(id){const u=db.users.find(x=>x.active&&(x.email.toLowerCase()===id.toLowerCase()||x.registration.toLowerCase()===id.toLowerCase()));if(!u)return toast('Conta não encontrada ou inativa. Confira a matrícula/e-mail.','error');db.session=u.id;save();closeModal();if(u.role==='librarian')openAdmin();else openAccount('overview');toast(`Bem-vindo(a), ${u.name.split(' ')[0]}!`)}
  function openAccount(tab='overview'){const u=current();if(!u)return openLogin();if(u.role==='librarian')return openAdmin();let tabs=[['overview','Resumo'],['loans','Meus empréstimos'],['reservations','Minhas reservas'],['history','Histórico'],['profile','Meus dados']];let content=accountContent(tab,u);openModal('Meu BiblioWeb',`<div class="account-layout"><aside class="account-sidebar"><div class="account-user"><div class="avatar">${u.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><strong>${escapeHTML(u.name)}</strong><small>Matrícula ${escapeHTML(u.registration)}</small></div>${tabs.map(([id,label])=>`<button class="account-tab ${id===tab?'active':''}" data-account-tab="${id}">${label}</button>`).join('')}<button class="account-tab" data-logout>↪ Sair da conta</button></aside><div class="account-main" id="account-main">${content}</div></div>`,'ÁREA DO USUÁRIO',true)}
  function accountContent(tab,u){let loans=activeLoans(u.id),reservations=db.reservations.filter(r=>r.userId===u.id&&['waiting','ready'].includes(r.status)),history=db.history.filter(h=>h.userId===u.id);if(tab==='overview')return `<h3>Olá, ${escapeHTML(u.name.split(' ')[0])}!</h3><p>Acompanhe sua situação na biblioteca e acesse rapidamente os serviços.</p><div class="metric-row"><div class="metric"><strong>${loans.length}</strong><span>Empréstimos ativos</span></div><div class="metric"><strong>${reservations.length}</strong><span>Reservas em andamento</span></div><div class="metric"><strong>${loans.filter(l=>l.dueDate<today()).length}</strong><span>Em atraso</span></div></div><h4 style="font:700 12px Manrope;color:var(--navy)">Próximas devoluções</h4>${loans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Devolução</th><th>Situação</th></tr></thead><tbody>${loans.map(l=>`<tr><td>${escapeHTML(book(l.bookId)?.title||'Material')}</td><td>${fmt(l.dueDate)}</td><td>${l.dueDate<today()?'<span class="status late">Em atraso</span>':'<span class="status available">No prazo</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tab-empty">Você não possui empréstimos ativos.</div>'}<div class="form-actions"><button class="btn btn-outline" data-account-tab="loans">Ver empréstimos</button><button class="btn btn-primary" data-account-tab="reservations">Ver reservas</button></div>`;
    if(tab==='loans')return `<h3>Meus empréstimos</h3><p>Confira os materiais emprestados e as respectivas datas de devolução.</p>${loans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Empréstimo</th><th>Devolução</th><th>Renovações</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${loans.map(l=>`<tr><td>${escapeHTML(book(l.bookId)?.title||'Material')}</td><td>${fmt(l.loanDate)}</td><td>${fmt(l.dueDate)}</td><td>${l.renewals}/${db.settings.maxRenewals}</td><td>${l.dueDate<today()?'<span class="status late">Em atraso</span>':'<span class="status available">Ativo</span>'}</td><td><button class="table-action" data-renew="${l.id}" ${l.dueDate<today()||l.renewals>=db.settings.maxRenewals||db.reservations.some(r=>r.bookId===l.bookId&&['waiting','ready'].includes(r.status))?'disabled':''}>Renovar</button></td></tr>`).join('')}</tbody></table></div><p class="form-help" style="margin-top:10px">A renovação é permitida até ${db.settings.maxRenewals} vezes, se o empréstimo estiver no prazo e não houver reserva pendente para o título.</p>`:'<div class="tab-empty">Você não possui empréstimos ativos.</div>'}`;
    if(tab==='reservations')return `<h3>Minhas reservas</h3><p>Acompanhe sua posição na fila e o prazo para retirada quando o material for liberado.</p>${reservations.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Solicitação</th><th>Situação</th><th>Posição/prazo</th><th>Ação</th></tr></thead><tbody>${reservations.map(r=>`<tr><td>${escapeHTML(book(r.bookId)?.title||'Material')}</td><td>${fmt(r.date)}</td><td>${r.status==='ready'?'<span class="status ready">Disponível para retirada</span>':'<span class="status borrowed">Aguardando</span>'}</td><td>${r.status==='ready'?`Até ${fmt(r.expiresAt)}`:`${reservationPosition(r)}º na fila`}</td><td><button class="table-action" data-cancel-res="${r.id}">Cancelar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="tab-empty">Você não possui reservas em andamento.</div>'}`;
    if(tab==='history')return `<h3>Histórico de circulação</h3><p>Consulte os empréstimos e devoluções registrados na sua conta.</p>${history.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Material</th><th>Empréstimo</th><th>Devolução</th><th>Registro</th></tr></thead><tbody>${history.map(h=>`<tr><td>${escapeHTML(book(h.bookId)?.title||'Material')}</td><td>${fmt(h.loanDate)}</td><td>${fmt(h.returnDate)}</td><td>Devolvido</td></tr>`).join('')}</tbody></table></div>`:'<div class="tab-empty">Seu histórico ainda está vazio.</div>'}`;
    return `<h3>Meus dados</h3><p>Confira seus dados de cadastro. Esta área é somente demonstrativa.</p><div class="form-grid"><div class="form-field"><label>Nome completo</label><input value="${escapeHTML(u.name)}" disabled></div><div class="form-field"><label>Matrícula</label><input value="${escapeHTML(u.registration)}" disabled></div><div class="form-field"><label>E-mail</label><input value="${escapeHTML(u.email)}" disabled></div><div class="form-field"><label>Curso</label><input value="${escapeHTML(u.course)}" disabled></div></div><div class="demo-note" style="margin-top:16px">Para atualizar dados cadastrais, procure o atendimento da biblioteca. A alteração de senha não está implementada porque este protótipo não utiliza autenticação real.</div>`}
  function reservationPosition(r){return db.reservations.filter(x=>x.bookId===r.bookId&&x.status==='waiting'&&x.date<=r.date).length}
  function renewLoan(id){const l=db.loans.find(x=>x.id===id),u=current();if(!l||!u||l.userId!==u.id)return;if(l.dueDate<today())return toast('Não é possível renovar: o empréstimo está em atraso.','error');if(l.renewals>=db.settings.maxRenewals)return toast('Limite de renovações atingido.','error');if(db.reservations.some(r=>r.bookId===l.bookId&&['waiting','ready'].includes(r.status)))return toast('Este título possui reserva pendente e não pode ser renovado.','error');l.dueDate=addDays(l.dueDate,db.settings.loanDays);l.renewals++;save();openAccount('loans');toast('Empréstimo renovado com sucesso.')}
  function cancelReservation(id){const r=db.reservations.find(x=>x.id===id),u=current();if(!r||!u||r.userId!==u.id)return;const wasReady=r.status==='ready';releaseReservationCopy(r);r.status='cancelled';r.cancelledAt=today();if(wasReady)promoteQueue(r.bookId);save();openAccount('reservations');toast('Reserva cancelada.')}
  function reserveBook(id,userId){const u=user(userId);const b=book(id);if(!u)return openLogin();if(!b)return;if(availableCopies(b)>0)return toast('Há exemplar disponível. Procure o balcão para realizar o empréstimo.','error');if(db.reservations.some(r=>r.userId===u.id&&r.bookId===id&&['waiting','ready'].includes(r.status)))return toast('Você já possui uma reserva ativa para este título.','error');let r={id:uid('R'),userId:u.id,bookId:id,date:today(),status:'waiting'};db.reservations.push(r);save();toast('Reserva registrada. Você entrou na fila de espera.');if(current()?.id===u.id)openAccount('reservations')}
  function releaseReservationCopy(r){if(r?.copyId){const c=copy(r.copyId);if(c&&c.status==='reserved')c.status='available';delete r.copyId}}
  function promoteQueue(bookId){const b=book(bookId);if(!b)return;const next=db.reservations.filter(r=>r.bookId===bookId&&r.status==='waiting').sort((a,b)=>a.date.localeCompare(b.date))[0];if(next){const c=b.copies.find(x=>x.status==='available');if(!c)return;c.status='reserved';next.copyId=c.id;next.status='ready';next.readyAt=today();next.expiresAt=addDays(today(),db.settings.holdDays||2)}}
  function returnLoan(id){const l=db.loans.find(x=>x.id===id);if(!l||l.status!=='active')return;const b=book(l.bookId),c=copy(l.copyId);l.status='returned';l.returnDate=today();if(c)c.status='available';db.history.push({id:uid('H'),userId:l.userId,bookId:l.bookId,loanDate:l.loanDate,returnDate:today()});promoteQueue(l.bookId);save();toast(`Devolução registrada: ${b?.title||'material'}.`);renderAdmin('loans')}
  function createLoan(userId,bookId){const u=user(userId),b=book(bookId);if(!u||!b)return toast('Usuário ou título não encontrado.','error');if(!u.active)return toast('Usuário inativo.','error');if(activeLoans(u.id).length>=db.settings.maxLoans)return toast('Este usuário atingiu o limite de empréstimos ativos.','error');if(activeLoans(u.id).some(l=>l.bookId===bookId))return toast('Este usuário já possui este título emprestado.','error');const c=b.copies.find(x=>x.status==='available');if(!c)return toast('Não há exemplares disponíveis para empréstimo.','error');c.status='borrowed';db.loans.push({id:uid('L'),userId:u.id,copyId:c.id,bookId,loanDate:today(),dueDate:addDays(today(),db.settings.loanDays),status:'active',renewals:0});save();toast('Empréstimo registrado com sucesso.');renderAdmin('loans')}
  function pickupReservation(id){const r=db.reservations.find(x=>x.id===id),u=r&&user(r.userId);if(!r||r.status!=='ready')return;if(!u?.active)return toast('A conta do usuário está inativa.','error');if(activeLoans(u.id).length>=db.settings.maxLoans)return toast('O usuário atingiu o limite de empréstimos.','error');const b=book(r.bookId),c=copy(r.copyId);if(!c||c.status!=='reserved')return toast('O exemplar reservado não está disponível.','error');c.status='borrowed';r.status='fulfilled';r.fulfilledAt=today();db.loans.push({id:uid('L'),userId:u.id,copyId:c.id,bookId:b.id,loanDate:today(),dueDate:addDays(today(),db.settings.loanDays),status:'active',renewals:0});save();toast('Retirada confirmada e empréstimo iniciado.');renderAdmin('reservations')}
  function openAdmin(section='dashboard'){const u=current();if(!u||u.role!=='librarian')return openLogin('librarian');openModal('Painel da biblioteca',`<div class="admin-shell"><div class="admin-top"><div><strong>Gestão da biblioteca</strong><br><span>Área administrativa • ${escapeHTML(u.name)}</span></div><button class="btn btn-outline btn-small" data-logout>Sair</button></div><div class="admin-layout"><aside class="admin-sidebar">${[['dashboard','Visão geral'],['books','Catálogo e exemplares'],['loans','Empréstimos'],['reservations','Reservas'],['users','Usuários'],['reports','Relatórios'],['settings','Configurações']].map(([id,label])=>`<button class="${section===id?'active':''}" data-admin-tab="${id}">${label}</button>`).join('')}</aside><div class="admin-main" id="admin-main">${adminContent(section)}</div></div></div>`,'PAINEL ADMINISTRATIVO',true)}
  function adminContent(section){let loans=activeLoans(),wait=db.reservations.filter(r=>['waiting','ready'].includes(r.status));if(section==='dashboard')return `<div class="admin-heading"><h3>Visão geral</h3><span class="form-help">Resumo da operação demonstrativa</span></div><div class="admin-kpis"><div class="admin-kpi"><strong>${db.books.length}</strong><span>Títulos no catálogo</span></div><div class="admin-kpi"><strong>${db.books.reduce((n,b)=>n+b.copies.length,0)}</strong><span>Exemplares</span></div><div class="admin-kpi"><strong>${loans.length}</strong><span>Empréstimos ativos</span></div><div class="admin-kpi"><strong>${wait.length}</strong><span>Reservas em andamento</span></div></div><div class="report-cards"><div class="report-card"><strong>Empréstimos em atraso</strong><span>${loans.filter(l=>l.dueDate<today()).length} registro(s) precisam de atenção.</span></div><div class="report-card"><strong>Usuários ativos</strong><span>${db.users.filter(u=>u.active&&u.role==='student').length} estudantes com acesso liberado.</span></div><div class="report-card"><strong>Exemplares disponíveis</strong><span>${db.books.reduce((n,b)=>n+availableCopies(b),0)} exemplar(es) podem ser emprestados.</span></div><div class="report-card"><strong>Fila de reservas</strong><span>${wait.filter(r=>r.status==='waiting').length} solicitação(ões) aguardando liberação.</span></div></div><div class="form-actions"><button class="btn btn-outline" data-admin-tab="loans">Gerenciar empréstimos</button><button class="btn btn-primary" data-admin-tab="books">Gerenciar catálogo</button></div>`;
    if(section==='books')return `<div class="admin-heading"><h3>Catálogo e exemplares</h3><button class="btn btn-primary btn-small" id="new-book">＋ Novo título</button></div><input class="admin-search" id="admin-filter" placeholder="Buscar por título, autor ou ISBN..."><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Título</th><th>Autor</th><th>Ano</th><th>Exemplares</th><th>Disponíveis</th><th>Ações</th></tr></thead><tbody>${db.books.map(b=>`<tr data-row-search="${escapeHTML((b.title+' '+b.author+' '+b.isbn).toLowerCase())}"><td><strong>${escapeHTML(b.title)}</strong><br><small>${b.id} • ${escapeHTML(b.subject)}</small></td><td>${escapeHTML(b.author)}</td><td>${b.year}</td><td>${b.copies.length}</td><td>${availableCopies(b)}</td><td><div class="admin-table-actions"><button data-edit-book="${b.id}">Editar</button><button data-add-copy="${b.id}">+ Exemplar</button><button class="danger" data-delete-book="${b.id}">Excluir</button></div></td></tr>`).join('')}</tbody></table></div>`;
    if(section==='loans')return `<div class="admin-heading"><h3>Empréstimos</h3><button class="btn btn-primary btn-small" id="new-loan">＋ Registrar empréstimo</button></div><input class="admin-search" id="admin-filter" placeholder="Buscar usuário ou material..."><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Usuário</th><th>Material</th><th>Empréstimo</th><th>Devolução</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${loans.map(l=>`<tr data-row-search="${escapeHTML(((user(l.userId)?.name||'')+' '+(book(l.bookId)?.title||'')).toLowerCase())}"><td>${escapeHTML(user(l.userId)?.name||'—')}<br><small>${escapeHTML(user(l.userId)?.registration||'')}</small></td><td>${escapeHTML(book(l.bookId)?.title||'—')}<br><small>${l.copyId}</small></td><td>${fmt(l.loanDate)}</td><td>${fmt(l.dueDate)}</td><td>${l.dueDate<today()?'<span class="status late">Em atraso</span>':'<span class="status available">Ativo</span>'}</td><td><button class="table-action" data-return="${l.id}">Registrar devolução</button></td></tr>`).join('')||'<tr><td colspan="6" class="tab-empty">Nenhum empréstimo ativo.</td></tr>'}</tbody></table></div>`;
    if(section==='reservations')return `<div class="admin-heading"><h3>Reservas</h3><span class="form-help">Fila de espera e retirada</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Usuário</th><th>Material</th><th>Solicitação</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${db.reservations.filter(r=>['waiting','ready'].includes(r.status)).map(r=>`<tr><td>${escapeHTML(user(r.userId)?.name||'—')}</td><td>${escapeHTML(book(r.bookId)?.title||'—')}</td><td>${fmt(r.date)}</td><td>${r.status==='ready'?`<span class="status ready">Retirar até ${fmt(r.expiresAt)}</span>`:'<span class="status borrowed">Aguardando</span>'}</td><td>${r.status==='ready'?`<button class="table-action" data-pickup="${r.id}">Confirmar retirada</button>`:'—'} <button class="table-action" data-admin-cancel-res="${r.id}">Cancelar</button></td></tr>`).join('')||'<tr><td colspan="5" class="tab-empty">Nenhuma reserva em andamento.</td></tr>'}</tbody></table></div>`;
    if(section==='users')return `<div class="admin-heading"><h3>Usuários</h3><button class="btn btn-primary btn-small" id="new-user">＋ Novo usuário</button></div><input class="admin-search" id="admin-filter" placeholder="Buscar por nome, matrícula ou e-mail..."><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Nome</th><th>Matrícula</th><th>Perfil</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${db.users.map(u=>`<tr data-row-search="${escapeHTML((u.name+' '+u.registration+' '+u.email).toLowerCase())}"><td>${escapeHTML(u.name)}<br><small>${escapeHTML(u.email)}</small></td><td>${escapeHTML(u.registration)}</td><td>${u.role==='librarian'?'Bibliotecário':'Estudante'}</td><td>${u.active?'<span class="status available">Ativo</span>':'<span class="status late">Inativo</span>'}</td><td><button class="table-action" data-toggle-user="${u.id}">${u.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div>`;
    if(section==='reports')return `<div class="admin-heading"><h3>Relatórios</h3><button class="btn btn-outline btn-small" id="export-data">Exportar dados JSON</button></div><div class="report-cards"><div class="report-card"><strong>Acervo por assunto</strong><span>${[...new Set(db.books.map(b=>b.subject))].map(s=>`${s}: ${db.books.filter(b=>b.subject===s).length}`).join(' • ')}</span></div><div class="report-card"><strong>Circulação</strong><span>${db.loans.length} empréstimos registrados no total; ${loans.length} ativos.</span></div><div class="report-card"><strong>Reservas</strong><span>${db.reservations.length} solicitações registradas.</span></div><div class="report-card"><strong>Usuários</strong><span>${db.users.length} cadastros; ${db.users.filter(u=>u.active).length} ativos.</span></div></div><div class="demo-note" style="margin-top:14px">Relatórios calculados localmente com os dados de demonstração. Não representam indicadores institucionais reais.</div>`;
    return `<div class="admin-heading"><h3>Configurações do protótipo</h3></div><div class="form-grid"><div class="form-field"><label>Prazo padrão de empréstimo (dias)</label><input type="number" id="setting-days" min="1" max="60" value="${db.settings.loanDays}"></div><div class="form-field"><label>Limite de empréstimos por usuário</label><input type="number" id="setting-limit" min="1" max="10" value="${db.settings.maxLoans}"></div><div class="form-field"><label>Máximo de renovações</label><input type="number" id="setting-renew" min="0" max="5" value="${db.settings.maxRenewals}"></div><div class="form-field"><label>Prazo de retirada da reserva (dias)</label><input type="number" id="setting-hold" min="1" max="7" value="2"></div></div><div class="form-actions"><button class="btn btn-primary" id="save-settings">Salvar configurações</button><button class="btn btn-outline" id="import-data">Importar backup JSON</button><button class="btn btn-outline" id="export-data">Exportar backup JSON</button></div><div class="demo-note" style="margin-top:15px"><strong>Aviso:</strong> as configurações e os dados são armazenados apenas neste navegador. Não há autenticação real, servidor ou banco de dados remoto.</div>`}
  function renderAdmin(section){const el=$('#admin-main');if(el)el.innerHTML=adminContent(section)}
  function openBookForm(id){const b=id?book(id):null;openModal(b?'Editar título':'Cadastrar novo título',`<form id="book-form" data-id="${b?.id||''}"><div class="form-grid"><div class="form-field full"><label for="bf-title">Título *</label><input id="bf-title" required value="${escapeHTML(b?.title||'')}"></div><div class="form-field"><label for="bf-author">Autor *</label><input id="bf-author" required value="${escapeHTML(b?.author||'')}"></div><div class="form-field"><label for="bf-publisher">Editora</label><input id="bf-publisher" value="${escapeHTML(b?.publisher||'')}"></div><div class="form-field"><label for="bf-year">Ano</label><input id="bf-year" type="number" min="1450" max="2100" value="${b?.year||new Date().getFullYear()}"></div><div class="form-field"><label for="bf-isbn">ISBN</label><input id="bf-isbn" value="${escapeHTML(b?.isbn||'')}"></div><div class="form-field"><label for="bf-type">Tipo de material</label><select id="bf-type">${['Livro','Livro digital','Periódico','Trabalho acadêmico'].map(x=>`<option ${b?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="bf-subject">Assunto</label><select id="bf-subject">${['Computação','Administração','Literatura','Engenharia','Educação','Outros'].map(x=>`<option ${b?.subject===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="bf-edition">Edição</label><input id="bf-edition" value="${escapeHTML(b?.edition||'1ª edição')}"></div><div class="form-field full"><label for="bf-description">Descrição</label><textarea id="bf-description">${escapeHTML(b?.description||'')}</textarea></div></div><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-admin="books">Cancelar</button><button class="btn btn-primary">Salvar título</button></div></form>`,'GESTÃO DO ACERVO')}
  function addCopy(id){const b=book(id);if(!b)return;const n=b.copies.length+1;b.copies.push({id:uid('EX'),location:`Estante • ${String(n).padStart(3,'0')}`,status:'available'});save();toast('Exemplar adicionado ao acervo.');renderAdmin('books')}
  function deleteBook(id){const b=book(id);if(!b)return;if(b.copies.some(c=>c.status==='borrowed')||db.reservations.some(r=>r.bookId===id&&['waiting','ready'].includes(r.status)))return toast('Não é possível excluir: há empréstimo ou reserva em andamento.','error');if(!confirm(`Excluir “${b.title}” do catálogo? Esta ação não pode ser desfeita.`))return;db.books=db.books.filter(x=>x.id!==id);save();toast('Título excluído do catálogo.');renderAdmin('books')}
  function openLoanForm(){const users=db.users.filter(u=>u.role==='student'&&u.active),available=db.books.filter(b=>availableCopies(b)>0);openModal('Registrar empréstimo',`<form id="loan-form"><div class="form-grid"><div class="form-field full"><label>Estudante *</label><select id="lf-user" required><option value="">Selecione o usuário</option>${users.map(u=>`<option value="${u.id}">${escapeHTML(u.name)} — ${escapeHTML(u.registration)}</option>`).join('')}</select></div><div class="form-field full"><label>Material disponível *</label><select id="lf-book" required><option value="">Selecione o título</option>${available.map(b=>`<option value="${b.id}">${escapeHTML(b.title)} (${availableCopies(b)} disponível(is))</option>`).join('')}</select></div></div><div class="demo-note" style="margin-top:14px">O sistema verifica automaticamente o limite de ${db.settings.maxLoans} empréstimos por estudante e a disponibilidade do exemplar.</div><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-admin="loans">Cancelar</button><button class="btn btn-primary">Confirmar empréstimo</button></div></form>`,'CIRCULAÇÃO')}
  function openUserForm(){openModal('Cadastrar usuário',`<form id="user-form"><div class="form-grid"><div class="form-field full"><label>Nome completo *</label><input id="uf-name" required></div><div class="form-field"><label>Matrícula *</label><input id="uf-reg" required></div><div class="form-field"><label>E-mail *</label><input id="uf-email" type="email" required></div><div class="form-field"><label>Perfil</label><select id="uf-role"><option value="student">Estudante</option><option value="librarian">Bibliotecário(a)</option></select></div><div class="form-field"><label>Curso / setor</label><input id="uf-course"></div></div><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-admin="users">Cancelar</button><button class="btn btn-primary">Cadastrar usuário</button></div></form>`,'GESTÃO DE USUÁRIOS')}
  function help(topic='general'){const content={search:['Como pesquisar no acervo',['Digite uma palavra-chave, título, autor, assunto, editora ou ISBN no campo de pesquisa.','Use “Pesquisa avançada” para combinar tipo de material, assunto, ano e disponibilidade.','Abra “Detalhes” para consultar descrição, edição, ISBN, localização e situação de cada exemplar.','Adicione materiais à cesta para montar uma lista de consulta.']],reserve:['Como fazer uma reserva',['Pesquise o título desejado e abra os detalhes.','A reserva fica disponível quando todos os exemplares estão emprestados.','Entre no Meu BiblioWeb para registrar a solicitação.','Acompanhe a fila em “Minhas reservas”. Quando liberado, o material ficará reservado por até dois dias.']],renew:['Como renovar um empréstimo',['Acesse “Meu BiblioWeb” e entre com sua conta.','Abra “Meus empréstimos” e localize o material.','Clique em “Renovar”.','A renovação só é permitida se o empréstimo estiver no prazo, não houver reserva pendente e o limite não tiver sido atingido.']],general:['Ajuda e orientações',['Consulta ao acervo: pesquisa por palavra-chave e filtros avançados.','Meu BiblioWeb: empréstimos, reservas, histórico e dados cadastrais.','Cesta: lista temporária de títulos para consulta.','Equipe da biblioteca: cadastro de títulos e exemplares, circulação, usuários e relatórios.','Este é um protótipo acadêmico: dados fictícios são armazenados no navegador.']]};let [title,steps]=content[topic]||content.general;openModal(title,`<div class="help-content"><p>Veja o passo a passo para utilizar este recurso.</p><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="demo-note">Se precisar de ajuda adicional, procure o atendimento da biblioteca.</div></div>`,'AJUDA E TUTORIAIS')}
  function exportData(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='biblioweb-backup.json';a.click();URL.revokeObjectURL(a.href);toast('Backup exportado.')}
  function importData(){const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=()=>{const file=input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data.books||!data.users||!data.loans||!data.reservations)throw Error('Estrutura inválida');if(!confirm('Substituir os dados atuais pelo backup selecionado?'))return;db=data;save();toast('Backup importado.');openAdmin('dashboard')}catch(e){toast('Não foi possível importar: arquivo inválido.','error')}};reader.readAsText(file)};input.click()}
  function expireReservations(){let changed=false;db.reservations.filter(r=>r.status==='ready'&&r.expiresAt<today()).forEach(r=>{const id=r.bookId;releaseReservationCopy(r);r.status='expired';promoteQueue(id);changed=true});if(changed)save()}
  function resetDemo(){if(!confirm('Restaurar todos os dados originais da demonstração? Suas alterações locais serão perdidas.'))return;db=seed();save();$('#basket-count').textContent='0';closeModal();renderCatalog();toast('Dados de demonstração restaurados.')}
  // Events — delegation keeps every dynamic control wired after re-render.
  document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;
    if(t.dataset.closeAdmin){const section=t.dataset.closeAdmin;closeModal();openAdmin(section);return}
    if(t.id==='modal-close'||t.hasAttribute('data-close-modal')){closeModal();return}
    if(t.id==='account-open'||t.id==='nav-login'||t.id==='notice-login'){openLogin();return}
    if(t.id==='admin-open'){openLogin('librarian');return}
    if(t.id==='basket-open'){openBasket();return}
    if(t.id==='help-open'){help();return}
    if(t.dataset.help){help(t.dataset.help);return}
    if(t.id==='advanced-toggle'){const p=$('#advanced-panel');p.hidden=!p.hidden;t.innerHTML=p.hidden?'Pesquisa avançada <span>＋</span>':'Ocultar filtros <span>−</span>';return}
    if(t.dataset.search){$('#search-query').value=t.dataset.search;lastQuery=t.dataset.search;visibleBooks=8;renderCatalog();goCatalog();return}
    if(t.dataset.page){$$('.nav-link').forEach(x=>x.classList.toggle('active',x===t));if(t.dataset.page==='catalogo'){e.preventDefault();goCatalog();return}}
    if(t.dataset.shortcut==='catalogo'){goCatalog();return}
    if(t.dataset.openAccount){openAccount(t.dataset.openAccount);return}
    if(t.dataset.detail){openBook(t.dataset.detail);return}
    if(t.dataset.basket){addBasket(t.dataset.basket);return}
    if(t.dataset.reserve){const u=current();if(!u)return openLogin();reserveBook(t.dataset.reserve,u.id);return}
    if(t.dataset.modalAction){const id=t.dataset.id,action=t.dataset.modalAction;if(action==='basket'){addBasket(id);closeModal()}if(action==='reserve'){const u=current();if(!u)return openLogin();closeModal();reserveBook(id,u.id)}return}
    if(t.dataset.removeBasket){db.basket=db.basket.filter(id=>id!==t.dataset.removeBasket);save();$('#basket-count').textContent=db.basket.length;openBasket();return}
    if(t.id==='basket-clear'){db.basket=[];save();$('#basket-count').textContent='0';openBasket();return}
    if(t.id==='basket-print'){window.print();return}
    if(t.dataset.fillLogin){const u=user(t.dataset.fillLogin);$('#login-id').value=u.email;$('#login-role').value=u.role;$('#login-password').value='demo';return}
    if(t.dataset.accountTab){const u=current();if(u)openAccount(t.dataset.accountTab);return}
    if(t.dataset.logout){db.session=null;save();closeModal();toast('Você saiu da sua conta.');return}
    if(t.dataset.renew){renewLoan(t.dataset.renew);return}
    if(t.dataset.cancelRes){const r=db.reservations.find(x=>x.id===t.dataset.cancelRes);if(r&&confirm('Cancelar esta reserva?')){const wasReady=r.status==='ready';releaseReservationCopy(r);r.status='cancelled';r.cancelledAt=today();if(wasReady)promoteQueue(r.bookId);save();openAccount('reservations');toast('Reserva cancelada.')}return}
    if(t.dataset.adminTab){renderAdmin(t.dataset.adminTab);$$('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b===t));return}
    if(t.dataset.editBook){openBookForm(t.dataset.editBook);return}
    if(t.dataset.addCopy){addCopy(t.dataset.addCopy);return}
    if(t.dataset.deleteBook){deleteBook(t.dataset.deleteBook);return}
    if(t.dataset.return){if(confirm('Confirmar a devolução deste material?'))returnLoan(t.dataset.return);return}
    if(t.dataset.pickup){pickupReservation(t.dataset.pickup);return}
    if(t.dataset.adminCancelRes){const r=db.reservations.find(x=>x.id===t.dataset.adminCancelRes);if(r&&confirm('Cancelar esta solicitação de reserva?')){const wasReady=r.status==='ready';releaseReservationCopy(r);r.status='cancelled';r.cancelledAt=today();if(wasReady)promoteQueue(r.bookId);save();renderAdmin('reservations');toast('Reserva cancelada.')}return}
    if(t.dataset.toggleUser){const u=user(t.dataset.toggleUser);if(!u)return;if(u.id===current()?.id)return toast('Não é possível desativar a própria conta.','error');u.active=!u.active;save();renderAdmin('users');toast(`Usuário ${u.active?'ativado':'desativado'}.`);return}
    if(t.id==='new-book'){openBookForm();return}if(t.id==='new-loan'){openLoanForm();return}if(t.id==='new-user'){openUserForm();return}
    if(t.id==='save-settings'){const days=+$('#setting-days').value,limit=+$('#setting-limit').value,renew=+$('#setting-renew').value,hold=+$('#setting-hold').value;if(![days,limit,renew,hold].every(Number.isFinite)||days<1||days>60||limit<1||limit>10||renew<0||renew>5||hold<1||hold>7)return toast('Confira os valores informados.','error');db.settings={loanDays:days,maxLoans:limit,maxRenewals:renew,holdDays:hold};save();toast('Configurações salvas.');return}
    if(t.id==='export-data'){exportData();return}if(t.id==='import-data'){importData();return}
    if(t.dataset.view){viewMode=t.dataset.view;$$('.view-toggle').forEach(x=>x.classList.toggle('active',x===t));renderCatalog();return}
    if(t.id==='show-all'){visibleBooks=db.books.length;$('#search-query').value='';lastQuery='';$('#filter-type').value='';$('#filter-subject').value='';$('#filter-year').value='';$('#filter-availability').value='';renderCatalog();goCatalog();return}
    if(t.id==='load-more'){visibleBooks+=8;renderCatalog();return}
    if(t.id==='reset-search'){resetSearch();return}
    if(t.id==='advanced-clear'){['filter-type','filter-subject','filter-year','filter-availability'].forEach(id=>$('#'+id).value='');return}
    if(t.id==='advanced-apply'){visibleBooks=8;renderCatalog();goCatalog();return}
    if(t.id==='reset-demo'){resetDemo();return}
    if(t.id==='contrast-toggle'){document.documentElement.classList.toggle('contrast-mode');t.setAttribute('aria-pressed',document.documentElement.classList.contains('contrast-mode'));return}
    if(t.id==='mobile-menu'){const nav=$('#main-nav'),open=nav.classList.toggle('open');t.setAttribute('aria-expanded',open);return}
  });
  document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form'){lastQuery=$('#search-query').value.trim();visibleBooks=8;renderCatalog();goCatalog();return}
    if(e.target.id==='login-form'){const id=$('#login-id').value.trim(),role=$('#login-role').value;const u=db.users.find(x=>x.active&&(x.email.toLowerCase()===id.toLowerCase()||x.registration.toLowerCase()===id.toLowerCase()));if(!u||u.role!==role)return toast('Confira matrícula/e-mail e tipo de acesso.','error');login(id);return}
    if(e.target.id==='book-form'){const id=e.target.dataset.id;const data={title:$('#bf-title').value.trim(),author:$('#bf-author').value.trim(),publisher:$('#bf-publisher').value.trim(),year:+$('#bf-year').value,isbn:$('#bf-isbn').value.trim(),type:$('#bf-type').value,subject:$('#bf-subject').value,edition:$('#bf-edition').value.trim(),description:$('#bf-description').value.trim()};if(!data.title||!data.author||data.year<1450||data.year>2100)return toast('Preencha título, autor e ano válido.','error');if(data.isbn&&db.books.some(b=>b.isbn===data.isbn&&b.id!==id))return toast('Já existe um título cadastrado com este ISBN.','error');if(id){Object.assign(book(id),data)}else{db.books.push({id:uid('B'),...data,cover:Math.ceil(Math.random()*8),copies:[{id:uid('EX'),location:'Estante • A definir',status:'available'}]})}save();closeModal();renderCatalog();openAdmin('books');toast('Cadastro salvo com sucesso.');return}
    if(e.target.id==='loan-form'){createLoan($('#lf-user').value,$('#lf-book').value);closeModal();openAdmin('loans');return}
    if(e.target.id==='user-form'){const name=$('#uf-name').value.trim(),registration=$('#uf-reg').value.trim(),email=$('#uf-email').value.trim();if(db.users.some(u=>u.registration.toLowerCase()===registration.toLowerCase()||u.email.toLowerCase()===email.toLowerCase()))return toast('Matrícula ou e-mail já cadastrado.','error');db.users.push({id:uid('U'),name,registration,email,role:$('#uf-role').value,course:$('#uf-course').value.trim(),active:true});save();closeModal();openAdmin('users');toast('Usuário cadastrado.');return}
  });
  document.addEventListener('input',e=>{if(e.target.id==='search-query'){$('#clear-search').style.display=e.target.value?'block':'none'}if(e.target.id==='admin-filter'){const q=e.target.value.toLowerCase();$$('[data-row-search]').forEach(row=>row.hidden=!row.dataset.rowSearch.includes(q))}});
  document.addEventListener('change',e=>{if(e.target.id==='sort-books')renderCatalog()});
  function resetSearch(){$('#search-query').value='';$('#search-field').value='all';['filter-type','filter-subject','filter-year','filter-availability'].forEach(id=>$('#'+id).value='');lastQuery='';visibleBooks=8;renderCatalog()}
  $('#clear-search').addEventListener('click',()=>{$('#search-query').value='';$('#clear-search').style.display='none';lastQuery='';renderCatalog()});
  $('#search-query').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#search-form').requestSubmit()}});
  $('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target===$('#modal-backdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal-backdrop').hidden)closeModal()});
  $('#mobile-menu').addEventListener('click',()=>{});
  expireReservations();$('#basket-count').textContent=db.basket.length;renderCatalog();save();
})();
